import { mkdir, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { componentMetas } from '@uigrove/components/meta'
import { generatedDir, registryDir } from './paths'
import { componentItem, hookItem, registryIndex, type RegistryItem } from './registry'
import { buildComponentVariants, buildHookVariants, hookName, type Variants } from './variants'

const readme = [
  'Generated by `pnpm registry` from packages/components. Do not edit by hand.',
  'variants.json holds the ts/js and tailwind/css variants of every component.',
  '',
].join('\n')

async function main() {
  await rm(registryDir, { recursive: true, force: true })
  await mkdir(registryDir, { recursive: true })
  await mkdir(generatedDir, { recursive: true })

  const variants: Record<string, Variants> = {}
  const items: RegistryItem[] = []

  for (const meta of componentMetas) {
    const built = await buildComponentVariants(meta.name)
    const item = componentItem(meta, built)
    variants[meta.name] = built
    items.push(item)
    await writeJson(path.join(registryDir, `${meta.name}.json`), item)
    console.log(`generated ${meta.name}`)
  }

  const hook = await buildHookVariants()
  const hookEntry = hookItem(hook)
  variants[hookName] = hook
  items.push(hookEntry)
  await writeJson(path.join(registryDir, `${hookName}.json`), hookEntry)
  await writeJson(path.join(registryDir, 'registry.json'), registryIndex(items))
  await writeJson(path.join(generatedDir, 'variants.json'), variants)
  await writeFile(path.join(generatedDir, 'README.md'), readme)
  console.log(`generated ${hookName}`)
}

function writeJson(file: string, data: unknown) {
  return writeFile(file, `${JSON.stringify(data, null, 2)}\n`)
}

main().catch((error: unknown) => {
  console.error(error)
  process.exitCode = 1
})
